"use client";
import { useRef } from "react";
import {
  TypeGlyphs,
  typeUnits,
  typeInteractive,
  useTypeMotion,
  type TypographyMotionProps,
} from "./typography-shared";
import { typeEaseOut, typeStaggerProgress } from "./typography-math";
export interface FoldingTextProps extends TypographyMotionProps {
  rotation?: number;
  perspective?: number;
  stagger?: number;
  axis?: "x" | "y";
}
export function FoldingText({
  text = "RUNNING SHOES",
  rotation = 100,
  perspective = 700,
  stagger = 0.6,
  axis = "x",
  ...props
}: FoldingTextProps) {
  const root = useRef<HTMLSpanElement>(null);
  useTypeMotion(
    root,
    props,
    (p) => {
      const units = typeUnits(root.current!);
      units.forEach((unit, i) => {
        const q = typeEaseOut(typeStaggerProgress(p, i, units.length, stagger));
        unit.style.transform = `perspective(${perspective}px) rotate${axis.toUpperCase()}(${rotation * (1 - q)}deg)`;
        unit.style.opacity = String(q);
        unit.style.filter = `brightness(${0.45 + 0.55 * q})`;
      });
    },
    `${text}:${rotation}:${perspective}:${stagger}:${axis}`,
  );
  return (
    <span
      ref={root}
      className={props.className}
      style={{ display: "inline-block", perspective, ...props.style }}
      aria-label={text}
      data-typography="folding-text"
      {...typeInteractive(props.trigger)}
    >
      <span aria-hidden="true">
        <TypeGlyphs text={text} />
      </span>
    </span>
  );
}
